          {expanded === i && <div className="ml-9 mt-3 rounded-lg bg-muted/50 p-3 text-sm"><p className="text-muted-foreground">{refused ? "This tool requested a permission outside its current scope." : `Details for ${title.toLowerCase()} with the input, output, and timing from this run.`}</p>{refused && <Button className="mt-3" size="sm" onClick={() => setRefusedOnly(false)}>Grant permission</Button>}{index === 0 && i === 4 && <div className="mt-3 flex flex-wrap gap-2"><Button size="sm" onClick={() => setStatus("Approved · Resuming")}>Approve</Button><Button variant="outline" size="sm" onClick={() => setStatus("Revision requested")}>Revise</Button><Button variant="outline" size="sm" onClick={() => setStatus("Run denied")}>Deny</Button></div>}</div>}
